import{_ as a,o as t,c as r,a0 as o}from"./chunks/framework.BQGW-Zpy.js";const n="/Cross-Border-Payments/assets/app-home.CQG0dktK.png",s="/Cross-Border-Payments/assets/app-send.DQCIYSmN.png",i="/Cross-Border-Payments/assets/app-transfers.sLGli6n8.png",l="/Cross-Border-Payments/assets/app-verify.DE5C_C_3.png",p="/Cross-Border-Payments/assets/app-community.Yry5E2xN.png",c="/Cross-Border-Payments/assets/app-profile.B2sdC6II.png",_=JSON.parse('{"title":"App Tour","description":"","frontmatter":{},"headers":[],"relativePath":"reference/app-tour.md","filePath":"reference/app-tour.md"}'),d={name:"reference/app-tour.md"};function h(m,e,u,f,b,g){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="app-tour" tabindex="-1">App Tour <a class="header-anchor" href="#app-tour" aria-label="Permalink to &quot;App Tour&quot;">​</a></h1><p>The app shell, a distinct mobile experience reachable at <code>/app</code>, with a screenshot of each screen. Opens with a tap-to-enter splash showing the full logo before landing on Home.</p><h2 id="home" tabindex="-1">Home <a class="header-anchor" href="#home" aria-label="Permalink to &quot;Home&quot;">​</a></h2><p><img src="'+n+'" alt="App Home"></p><p>The main screen: a balance card on the Hedera testnet, quick actions (Send, Convert, Verify, More), a &quot;Recent activity&quot; list pulled from the real backend, and a callout linking straight to the real anchored records on the Hedera Mirror Node.</p><h2 id="send" tabindex="-1">Send <a class="header-anchor" href="#send" aria-label="Permalink to &quot;Send&quot;">​</a></h2><p><img src="'+s+'" alt="App Send"></p><p>A compact, native four-step transfer flow living entirely inside the app shell, amount and currency, recipient and country, payout method, review, using the same real calculation utilities and the same real transfer-creation API as the web version, not a separate simulation. Ends with a Community Usage Code card when the resulting transaction has a real Hedera anchor.</p><h2 id="transfers" tabindex="-1">Transfers <a class="header-anchor" href="#transfers" aria-label="Permalink to &quot;Transfers&quot;">​</a></h2><p><img src="'+i+'" alt="App Transfers"></p><p>The full transfer history, fetched from the real backend first (falling back to this device&#39;s local history only if the backend can&#39;t be reached), with a &quot;New transfer&quot; action leading into the same Send flow above.</p><h2 id="verify" tabindex="-1">Verify <a class="header-anchor" href="#verify" aria-label="Permalink to &quot;Verify&quot;">​</a></h2><p><img src="'+l+'" alt="App Verify"></p><p>Enter any transaction ID to verify its compliance record against the real Hedera Mirror Node. Uses a minimal, hollow-outline shield icon rather than a filled badge. Includes a working example (<code>TXN-9KF3XQ2</code>) for a quick, real check.</p><h2 id="community" tabindex="-1">Community <a class="header-anchor" href="#community" aria-label="Permalink to &quot;Community&quot;">​</a></h2><p><img src="'+p+'" alt="App Community"></p><p>The same Community feature as the web version, native to the app shell: a form requiring a real Community Usage Code plus a message, and the public feed of posts below it.</p><h2 id="profile" tabindex="-1">Profile <a class="header-anchor" href="#profile" aria-label="Permalink to &quot;Profile&quot;">​</a></h2><p><img src="'+c+'" alt="App Profile"></p><p>Account info, appearance (light/dark) toggle, KYC/AML compliance status, links to full documentation and feedback, and a reset-demo-data control.</p><h2 id="tab-bar" tabindex="-1">Tab bar <a class="header-anchor" href="#tab-bar" aria-label="Permalink to &quot;Tab bar&quot;">​</a></h2><p>Five tabs sit at the bottom of every screen: Home, Transfers, Verify, Community, Profile. The active tab gets a soft rounded highlight behind its icon and a bolder stroke weight.</p>',22)])])}const k=a(d,[["render",h]]);export{_ as __pageData,k as default};
